import{_ as e,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const q=JSON.parse('{"title":"设置和配置 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"数据库设置","slug":"数据库设置","link":"#数据库设置","children":[{"level":3,"title":"写入设置模型","slug":"写入设置模型","link":"#写入设置模型","children":[]},{"level":3,"title":"从设置模型中读取","slug":"从设置模型中读取","link":"#从设置模型中读取","children":[]}]},{"level":2,"title":"后端设置页面","slug":"后端设置页面","link":"#后端设置页面","children":[{"level":3,"title":"设置链接注册","slug":"设置链接注册","link":"#设置链接注册","children":[]},{"level":3,"title":"设置页面导航上下文","slug":"设置页面导航上下文","link":"#设置页面导航上下文","children":[]}]},{"level":2,"title":"基于文件的配置","slug":"基于文件的配置","link":"#基于文件的配置","children":[{"level":3,"title":"覆盖配置值","slug":"覆盖配置值","link":"#覆盖配置值","children":[]}]}],"relativePath":"2.x/zh-cn/plugin/settings.md","filePath":"2.x/zh-cn/plugin/settings.md"}'),r={name:"2.x/zh-cn/plugin/settings.md"};function u(g,n,k,d,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"设置和配置",-1)),a(p),n[1]||(n[1]=i(`<p>有两种配置插件的方法 - 使用后端设置表单和配置文件。将数据库设置与后端页面一起使用可提供更好的用户体验，但它们会为初始开发带来更多开销。基于文件的配置适用于很少修改的配置。</p><p><a id="oc-database-settings"></a></p><h2 id="数据库设置"><a href="#数据库设置" class="header-anchor">#</a> 数据库设置</h2><p>您可以通过在模型类中实现<code>SettingsModel</code>行为来创建用于在数据库中存储设置的模型。此模型可直接用于创建后端设置表单。您不需要创建数据库表和控制器。</p><p>设置模型类应该扩展模型类并实现 <code>\\System\\Behaviors\\SettingsModel</code> 行为。设置模型像其他任何模型一样，应该在插件目录的 <strong>models</strong> 子目录中定义。下一个示例中的模型应该在<code>plugins/acme/demo/models/Settings.php</code> 脚本中定义。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Settings</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>SettingsModel</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token comment">// 独一无二的标识符</span>
    <span class="token keyword">public</span> <span class="token variable">$settingsCode</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_demo_settings&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">// 参考字段配置</span>
    <span class="token keyword">public</span> <span class="token variable">$settingsFields</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;fields.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</span></code></pre></div><p>设置模型需要 <code>$settingsCode</code> 属性。 它定义了用于将设置保存到数据库的唯一设置键。</p><p>如果要基于模型构建后端设置表单，则需要 <code>$settingsFields</code> 属性。 该属性指定包含表单字段定义的 YAML 文件的名称。 <a href="./../backend/forms.html">后端表单</a> 文章中描述了表单字段。 YAML 文件应放在名称与模型类名称匹配的小写目录中。 对于上一个示例中的模型，目录结构如下所示：</p><div class="language- extra-class"><pre class="language-text"><code>plugins/
    acme/
    demo/
        models/
        settings/        &lt;=== 文件目录
            fields.yaml  &lt;=== 表单文件
        Settings.php     &lt;=== 脚本
</code></pre></div><p>设置模型<a href="#oc-backend-settings-pages">可以注册</a> 出现在<strong>后端设置页面</strong>，但这不是必需的 - 您可以像任何其他模型一样设置和读取设置值。</p><h3 id="写入设置模型"><a href="#写入设置模型" class="header-anchor">#</a> 写入设置模型</h3><p>设置模型具有静态<code>set</code> 方法，允许保存单个或多个值。 您还可以使用标准模型功能来设置模型属性和保存模型。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Settings</span><span class="token punctuation">;</span>

<span class="token comment">// 设置单个值</span>
<span class="token class-name static-context">Settings</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 设置一组值</span>
<span class="token class-name static-context">Settings</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;api_key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 设置对象值</span>
<span class="token variable">$settings</span> <span class="token operator">=</span> <span class="token class-name static-context">Settings</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$settings</span><span class="token operator">-&gt;</span><span class="token property">api_key</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;ABCD&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$settings</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="从设置模型中读取"><a href="#从设置模型中读取" class="header-anchor">#</a> 从设置模型中读取</h3><p>设置模型具有静态<code>get</code> 方法，使您能够加载单个属性。 此外，当您使用 <code>instance</code> 方法实例化模型时，它会从数据库加载属性，您可以直接访问它们。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 输出：ABCD</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">Settings</span><span class="token operator">::</span><span class="token function">instance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">api_key</span><span class="token punctuation">;</span>

<span class="token comment">// 获取单个值</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">Settings</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;api_key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 获取一个值，如果不存在则返回一个默认值</span>
<span class="token keyword">echo</span> <span class="token class-name static-context">Settings</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_activated&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-backend-settings-pages"></a></p><h2 id="后端设置页面"><a href="#后端设置页面" class="header-anchor">#</a> 后端设置页面</h2><p>后端包含用于系统和和插件配置的专用区域，可以通过单击主菜单中的<strong>设置</strong>链接进行访问</p><p><a id="oc-settings-link-registration"></a></p><h3 id="设置链接注册"><a href="#设置链接注册" class="header-anchor">#</a> 设置链接注册</h3><p>可以通过覆盖<a href="./registration.html#oc-registration-file">插件注册类</a>中的<code>registerSettings</code>方法来扩展后端设置导航链接。 创建配置链接时，您有两个选项 - 创建指向特定后端页面的链接，或创建指向设置模型的链接。 下一个示例显示如何创建指向后端页面的链接。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;location&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;地理位置&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;管理可用的用户国家和州。&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Users&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-globe&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/user/locations&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keywords&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;地理 地点 位置&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>注意</strong>：后端设置页面应该<a href="#oc-setting-the-page-navigation-context">配置设置的上下文</a>，以便在系统页面侧边栏中标记相应的设置菜单项是否处于活动状态。 自动检测设置模型的设置上下文。</p></blockquote><p>以下示例创建指向设置模型的链接。 设置模型是上面<a href="#oc-database-settings">数据库设置</a> 部分中描述的设置API 的一部分。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;settings&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;用户设置&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;管理基于用户的设置。&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Users&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-cog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>Settings</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keywords&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;账号 头像 会员信息&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.users.access_settings&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>设置搜索功能使用可选的<code>keywords</code> 参数。 如果未提供关键字，则搜索仅使用设置项标签和描述。</p><p><a id="oc-setting-the-page-navigation-context"></a></p><h3 id="设置页面导航上下文"><a href="#设置页面导航上下文" class="header-anchor">#</a> 设置页面导航上下文</h3><p>就像<a href="./../backend/controllers-ajax.html#oc-setting-the-navigation-context">在控制器中设置导航上下文</a> 一样，后端设置页面应该配置设置的导航上下文。 为了将系统页面侧栏中的当前设置链接标记为活动，这是必需的。 使用<code>System\\Classes\\SettingsManager</code>类来设置设置上下文。 通常它可以在控制器构造函数中完成：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword static-context">parent</span><span class="token operator">::</span><span class="token function">__construct</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span>

    <span class="token class-name static-context">BackendMenu</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;October.System&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;system&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;settings&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name static-context">SettingsManager</span><span class="token operator">::</span><span class="token function">setContext</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;You.Plugin&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;settings&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p><code>setContext</code> 方法的第一个参数是以下格式的设置项所有者：<strong>author.plugin</strong>。 第二个参数是设置名称，与您在<a href="#oc-settings-link-registration">注册后端设置页面</a>时提供的相同。</p><p><a id="oc-file-based-configuration"></a></p><h2 id="基于文件的配置"><a href="#基于文件的配置" class="header-anchor">#</a> 基于文件的配置</h2><p>插件可以在插件目录的<strong>config</strong> 子目录下有一个配置文件<strong>config.php</strong>。 配置文件是定义并返回 <strong>array</strong> 的 PHP 脚本。 示例配置文件 <strong>plugins/acme/demo/config/config.php</strong>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;display&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">5</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>使用 <code>Config</code> 类来访问配置文件中定义的配置值。 <code>Config::get($name, $default = null)</code> 方法接受以下格式的插件和参数名称：<strong>Acme.Demo::maxItems</strong>。 第二个可选参数定义了如果配置参数不存在则返回的默认值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以为配置文件使用不同的文件名，这会影响键名。 例如，名为 <strong>custom.php</strong> 的配置文件将使用 <code>custom</code> 作为键名的前缀，使用以下格式：<strong>Acme.Demo::custom.maxItems</strong>。 示例配置文件 <strong>plugins/acme/demo/config/custom.php</strong>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$maxItems</span> <span class="token operator">=</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.demo::custom.maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="覆盖配置值"><a href="#覆盖配置值" class="header-anchor">#</a> 覆盖配置值</h3><p>一个插件配置文件可以被应用程序覆盖，通过创建一个本地配置文件来匹配，例如覆盖<strong>plugins/acme/demo/config/config.php</strong>，创建一个名为<strong>config/acme/todo/config.php</strong>的文件。 在覆盖的配置文件中，您可以只设置要覆盖的值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">20</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>如果您想在不同的环境中使用单独的配置(例如：<strong>dev</strong>、<strong>production</strong>)，请考虑使用 <code>env()</code> 助手从环境变量中提取值。 <code>env($name, $default = null)</code> 函数接受环境变量名称和一个默认值(如果变量不存在)。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;ACME_TODO_MAX_ITEMS&#39;</span><span class="token punctuation">,</span> <span class="token number">25</span><span class="token punctuation">)</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</span></code></pre></div><p>当环境变量<code>ACME_TODO_MAX_ITEMS</code>设置为任何其他值时，这将更改<code>maxItems</code>值。</p>`,46))])}const v=e(r,[["render",u]]);export{q as __pageData,v as default};
